def _make_task(
    pattern_refs: list[str] | None = None,
    title: str = "Test Task",
) -> TaskRecord:
    """Construct a minimal TaskRecord for subgraph tests."""
    return TaskRecord(
        id           = str(uuid.uuid4()),
        title        = title,
        description  = "A test task â€” build the thing.",
        order_index  = 0,
        pattern_refs = pattern_refs or [],
        status       = TaskStatus.IN_PROGRESS.value,
    )


def _initial_state(task: TaskRecord, max_retries: int = 3) -> dict:
    """Construct a clean initial TaskState dict for subgraph invocation."""
    return {
        "run_id":               "run-test-001",
        "project_id":           "proj-test-001",
        "task":                 task.to_dict(),
        "requirements_context": "Build a multi-agent LangGraph system.",
        "architecture_context": '{"nodes": ["planner", "executor"]}',
        "max_retries":          max_retries,
        "developer_output":     None,
        "pending_files":        [],
        "critic_feedback":      None,
        "reviewer_verdicts":    [],
        "review_passed":        False,
        "aggregated_feedback":  None,
        "retry_count":          0,
        "final_status":         None,
        "generated_files":      [],
        "error":                None,
    }


