class TestReflectionTopology:
    """
    Tests for tasks with pattern_refs=["Reflection"].
    Inserts critic_node between developer_node and reviewer fan-out.
    """

    @pytest.mark.asyncio
    async def test_critic_passes_first_time(self, mock_openai):
        """
        Critic approves on first attempt.
        Graph proceeds directly to reviewers â€” no revision cycle.
        LLM calls: 1 developer + 1 critic + 3 reviewers = 5 total.
        """
        task = _make_task(pattern_refs=["Reflection"])

        mock_openai.side_effect = [
            make_developer_response({"src/loop.py": "for i in range(n): pass"}),
            make_critic_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        subgraph    = build_task_subgraph(task, max_retries=3)
        final_state = await subgraph.ainvoke(
            _initial_state(task),
            config={"recursion_limit": 50},
        )

        assert final_state["final_status"] == TaskStatus.COMPLETED.value
        assert "src/loop.py" in final_state["generated_files"]
        assert mock_openai.call_count == 5

    @pytest.mark.asyncio
    async def test_critic_fails_once_then_passes(self, mock_openai):
        """
        Critic identifies a problem.
        Developer revises.
        Critic approves the revision.
        Reviewers all pass.
        Task completes.
        """
        task = _make_task(pattern_refs=["Reflection"])

        mock_openai.side_effect = [
            # Developer attempt 1
            make_developer_response({"src/loop.py": "while True: pass"}),
            # Critic: fail
            make_critic_fail_response("Loop is unbounded."),
            # Developer revision (attempt 2)
            make_developer_response({"src/loop.py": "for i in range(max_iter): pass"}),
            # Critic: pass
            make_critic_pass_response(),
            # Three reviewers pass
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        subgraph    = build_task_subgraph(task, max_retries=3)
        final_state = await subgraph.ainvoke(
            _initial_state(task),
            config={"recursion_limit": 50},
        )

        assert final_state["final_status"] == TaskStatus.COMPLETED.value
        # critic_feedback should be cleared after passing
        assert not final_state.get("critic_feedback")

    @pytest.mark.asyncio
    async def test_critic_fail_followed_by_reviewer_fail_then_recovery(
        self, mock_openai
    ):
        """
        Critic fails once (inner loop revision).
        After critic passes, one reviewer fails (outer retry loop).
        Developer retries again.
        All reviewers pass on second outer attempt.
        """
        task = _make_task(pattern_refs=["Reflection"])

        mock_openai.side_effect = [
            # Developer attempt 1
            make_developer_response({"src/a.py": "v1"}),
            # Critic fail
            make_critic_fail_response("Issue found."),
            # Developer revision
            make_developer_response({"src/a.py": "v2"}),
            # Critic pass
            make_critic_pass_response(),
            # Reviewer fail on first outer attempt
            make_reviewer_fail_response(feedback="Needs improvement."),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            # Developer retry (outer)
            make_developer_response({"src/a.py": "v3"}),
            # Critic pass (second outer attempt enters critic again)
            make_critic_pass_response(),
            # All reviewers pass
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        subgraph    = build_task_subgraph(task, max_retries=3)
        final_state = await subgraph.ainvoke(
            _initial_state(task),
            config={"recursion_limit": 50},
        )

        assert final_state["final_status"] == TaskStatus.COMPLETED.value

    @pytest.mark.asyncio
    async def test_reflection_retry_cap_exhausted(self, mock_openai):
        """
        Critic keeps failing. Retry count increments per developer call.
        When retry_count exceeds max_retries, route_after_reduce sends to FAIL.
        Note: critic failures count against the retry budget via retry_count
        increment in developer_node â€” the same budget governs both loops.
        """
        task = _make_task(pattern_refs=["Reflection"])

        # max_retries=1: critic will fail both attempts
        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "v1"}),
            make_critic_fail_response("Still broken."),
            make_developer_response({"src/a.py": "v2"}),
            make_critic_fail_response("Still broken."),
            make_developer_response({"src/a.py": "v3"}),
            make_critic_pass_response(),          # eventually passes critic
            make_reviewer_fail_response(),        # but reviewer blocks
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        subgraph    = build_task_subgraph(task, max_retries=1)
        final_state = await subgraph.ainvoke(
            _initial_state(task, max_retries=1),
            config={"recursion_limit": 50},
        )

        # With max_retries=1, cap is hit before reviewers can pass
        assert final_state["final_status"] == TaskStatus.FAILED.value


