# ===========================================================================

class TestEdgeCases:

    @pytest.mark.asyncio
    async def test_developer_parse_failure_marks_task_failed(self, mock_openai):
        """
        Developer returns prose with no <file> blocks.
        parse_developer_output raises ValueError.
        developer_node sets state["error"] and pending_files=[].
        finalize_task_node marks the task FAILED.
        No files written to disk.
        """
        task = _make_task(pattern_refs=[])

        mock_openai.return_value = _make_chat_response(
            "I have analysed the requirements. Here is my plan: ..."
        )

        subgraph    = build_task_subgraph(task, max_retries=1)
        final_state = await subgraph.ainvoke(
            _initial_state(task, max_retries=1),
            config={"recursion_limit": 50},
        )

        assert final_state["final_status"] == TaskStatus.FAILED.value
        assert final_state["generated_files"] == []
        mock_file_store.save_workspace_file.assert_not_called()

    @pytest.mark.asyncio
    async def test_developer_llm_exception_marks_task_failed(self, mock_openai):
        """
        OpenAI call raises a connection error.
        developer_node catches it and sets state["error"].
        Task ultimately fails gracefully â€” no unhandled exception propagates.
        """
        task = _make_task(pattern_refs=[])

        mock_openai.side_effect = Exception("Connection reset by peer.")

        subgraph    = build_task_subgraph(task, max_retries=1)
        final_state = await subgraph.ainvoke(
            _initial_state(task, max_retries=1),
            config={"recursion_limit": 50},
        )

        assert final_state["final_status"] == TaskStatus.FAILED.value
        assert "Connection reset" in (final_state.get("error") or "")

    @pytest.mark.asyncio
    async def test_reviewer_llm_exception_is_blocking_not_silent_pass(
        self, mock_openai
    ):
        """
        One reviewer's LLM call raises an exception.
        _call_reviewer() catches it and returns a blocking ReviewerVerdict
        with passed=False.  The task fails â€” an infrastructure error does
        not silently pass a review.
        """
        task = _make_task(pattern_refs=[])

        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            Exception("Reviewer LLM timeout."),  # workflow_reviewer fails
            make_reviewer_pass_response(),        # prompt_reviewer passes
            make_reviewer_pass_response(),        # security_reviewer passes
        ]

        subgraph    = build_task_subgraph(task, max_retries=0)
        final_state = await subgraph.ainvoke(
            _initial_state(task, max_retries=0),
            config={"recursion_limit": 50},
        )

        # max_retries=0 means the single failure immediately exhausts the cap
        assert final_state["final_status"] == TaskStatus.FAILED.value

    @pytest.mark.asyncio
    async def test_empty_file_content_still_written(self, mock_openai):
        """
        Developer produces a file with empty content.
        Empty files are valid â€” written to disk, task completes.
        """
        task = _make_task(pattern_refs=[])

        mock_openai.side_effect = [
            make_developer_response({"src/__init__.py": ""}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        subgraph    = build_task_subgraph(task, max_retries=3)
        final_state = await subgraph.ainvoke(
            _initial_state(task),
            config={"recursion_limit": 50},
        )

        assert final_state["final_status"] == TaskStatus.COMPLETED.value
        assert "src/__init__.py" in final_state["generated_files"]

    @pytest.mark.asyncio
    async def test_max_retries_zero_means_one_attempt_only(self, mock_openai):
        """
        max_retries=0 allows exactly one attempt.
        If reviewers fail, the task immediately fails â€” no retry cycle.
        """
        task = _make_task(pattern_refs=[])

        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            make_reviewer_fail_response(feedback="Instant fail."),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        subgraph    = build_task_subgraph(task, max_retries=0)
        final_state = await subgraph.ainvoke(
            _initial_state(task, max_retries=0),
            config={"recursion_limit": 50},
        )

        assert final_state["final_status"] == TaskStatus.FAILED.value
        # Developer was called exactly once
        # (1 dev + 3 reviewers = 4 total calls)
        assert mock_openai.call_count == 4

    @pytest.mark.asyncio
    async def test_last_file_write_fails_task_marked_failed(self, mock_openai):
        """
        Review passes but every file write raises an exception.
        finalize_task_node catches the write errors.
        Task is marked FAILED (no files successfully written).
        """
        task = _make_task(pattern_refs=[])

        mock_openai.side_effect = [
            make_developer_response({"src/a.py": "pass"}),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
            make_reviewer_pass_response(),
        ]

        mock_file_store.save_workspace_file.side_effect = OSError("Disk full.")

        subgraph    = build_task_subgraph(task, max_retries=3)
        final_state = await subgraph.ainvoke(
            _initial_state(task),
            config={"recursion_limit": 50},
        )

        assert final_state["final_status"] == TaskStatus.FAILED.value
        assert final_state["generated_files"] == []


# ===========================================================================
# COMPILATION CACHE
# ===========================================================================

class TestCompilationCache:

    def test_same_patterns_returns_cached_instance(self):
        """
        Two calls with identical pattern_refs return the same object.
        """
        t1 = _make_task(pattern_refs=["Reflection"])
        t2 = _make_task(pattern_refs=["Reflection"])

        g1 = build_task_subgraph(t1)
        g2 = build_task_subgraph(t2)

        assert g1 is g2

    def test_different_patterns_return_distinct_instances(self):
        """
        All four topology combinations produce distinct compiled graphs.
        """
        t_base    = _make_task(pattern_refs=[])
        t_reflect = _make_task(pattern_refs=["Reflection"])
        t_tool    = _make_task(pattern_refs=["Tool-Use"])
        t_both    = _make_task(pattern_refs=["Reflection", "Tool-Use"])

        g_base    = build_task_subgraph(t_base)
        g_reflect = build_task_subgraph(t_reflect)
        g_tool    = build_task_subgraph(t_tool)
        g_both    = build_task_subgraph(t_both)

        ids = {id(g_base), id(g_reflect), id(g_tool), id(g_both)}
        assert len(ids) == 4

    def test_pattern_order_irrelevant_for_cache_key(self):
        """
        ["Reflection", "Tool-Use"] and ["Tool-Use", "Reflection"]
        resolve to the same frozenset cache key and return the same graph.
        """
        t_a = _make_task(pattern_refs=["Reflection", "Tool-Use"])
        t_b = _make_task(pattern_refs=["Tool-Use", "Reflection"])

        g_a = build_task_subgraph(t_a)
        g_b = build_task_subgraph(t_b)

        assert g_a is g_b

    def test_unknown_patterns_do_not_create_new_topology(self):
        """
        An unrecognised pattern tag is silently ignored for topology purposes.
        A task with ["UnknownPattern"] compiles the same base topology as [].
        The two graphs are the same cached instance.
        """
        t_unknown = _make_task(pattern_refs=["UnknownPattern"])
        t_base    = _make_task(pattern_refs=[])

        g_unknown = build_task_subgraph(t_unknown)
        g_base    = build_task_subgraph(t_base)

        # frozenset(["UnknownPattern"]) != frozenset([]) so they are cached
        # separately, but both should compile to the base topology successfully.
        assert g_unknown is not None
        assert g_base    is not None

    def test_clear_cache_removes_all_entries(self):
        """
        clear_subgraph_cache() empties _SUBGRAPH_CACHE.
        After clearing, a fresh compile produces a new graph instance.
        """
        task = _make_task(pattern_refs=["Reflection"])

        g_before = build_task_subgraph(task)
        assert len(_SUBGRAPH_CACHE) > 0

        clear_subgraph_cache()
        assert len(_SUBGRAPH_CACHE) == 0

        g_after = build_task_subgraph(task)
        # Different instance â€” cache was cleared and recompiled
        assert g_before is not g_after

    def test_get_cached_patterns_returns_current_keys(self):
        """
        get_cached_patterns() reflects what is currently in the cache.
        """
        _make_task(pattern_refs=[])
        _make_task(pattern_refs=["Reflection"])

        build_task_subgraph(_make_task(pattern_refs=[]))
        build_task_subgraph(_make_task(pattern_refs=["Reflection"]))

        cached = get_cached_patterns()
        assert [] in cached
        assert ["Reflection"] in cached

    def test_cache_populated_after_first_compile(self):
        """
        Cache is empty before any build call (reset_subgraph_cache runs before each test).
        After one build, cache has exactly one entry.
        """
        assert len(_SUBGRAPH_CACHE) == 0

        task = _make_task(pattern_refs=["Tool-Use"])
        build_task_subgraph(task)

        assert len(_SUBGRAPH_CACHE) == 1
        assert frozenset(["Tool-Use"]) in _SUBGRAPH_CACHE


